@@ -0,0 +1,32 @@
+/**
+ * Briefing generator for the rebase executor variant.
+ *
+ * No mgmt repo clone is needed — the rebase briefing is derived entirely from
+ * env vars (TASK_REPO_BRANCH, TASK_BASE_BRANCH). Replaces the 4-line inline
+ * string the orchestrator used to build directly in main.ts.
+ */
+
+export interface RebaseBriefingOpts {
+  taskId: string;
+  /** The task branch with a PR conflict (TASK_REPO_BRANCH). */
+  taskRepoBranch: string;
+  /** The PR target / rebase base (TASK_BASE_BRANCH, e.g. feature/<featureId>). */
+  taskBaseBranch: string;
+}
+
+/**
+ * Generate the rebase executor briefing.
+ *
+ * Instructs the executor to rebase the task branch onto the feature branch
+ * and resolve any conflicts. Matches the inline string the orchestrator
+ * previously built at main.ts:709.
+ */
+export function generateRebaseBriefing(opts: RebaseBriefingOpts): string {
+  const { taskId, taskRepoBranch, taskBaseBranch } = opts;
+  return [
+    `# Rebase: ${taskId}`,
+    ``,
+    `Branch \`${taskRepoBranch}\` has a PR conflict (mergeable: false).`,
+    `Rebase it onto \`${taskBaseBranch}\` and resolve any conflicts.`,
+  ].join("\n");
+}
