+/**
+ * Executor briefing module — self-contained prompt construction.
+ *
+ * The executor clones the mgmt repo and calls buildBriefing() to produce
+ * the initial Claude prompt without any orchestrator briefing logic.
+ */
+
+import { generateBriefing, type ImplBriefingOpts } from "./agent-context.js";
+import { generateFixBriefing, type FixBriefingOpts } from "./fix-briefing.js";
+import { generateReviewerBriefing, type ReviewerBriefingOpts } from "./reviewer-briefing.js";
+import { generateRebaseBriefing, type RebaseBriefingOpts } from "./rebase-briefing.js";
+
+export type BriefingKind = "impl" | "fix" | "reviewer" | "rebase";
+
+export type {
+  ImplBriefingOpts,
+  FixBriefingOpts,
+  ReviewerBriefingOpts,
+  RebaseBriefingOpts,
+};
+
+export type BuildBriefingOpts =
+  | ({ kind: "impl" } & ImplBriefingOpts)
+  | ({ kind: "fix" } & FixBriefingOpts)
+  | ({ kind: "reviewer" } & ReviewerBriefingOpts)
+  | ({ kind: "rebase" } & RebaseBriefingOpts);
+
+/**
+ * Build the executor briefing for the given kind.
+ *
+ * For impl/fix/reviewer: reads task title from the cloned mgmt repo.
+ * For rebase: derives context from env-var fields only (no mgmt repo read).
+ */
+export function buildBriefing(mgmtDir: string, opts: BuildBriefingOpts): string {
+  switch (opts.kind) {
+    case "impl":
+      return generateBriefing(mgmtDir, opts);
+    case "fix":
+      return generateFixBriefing(mgmtDir, opts);
+    case "reviewer":
+      return generateReviewerBriefing(mgmtDir, opts);
+    case "rebase":
+      return generateRebaseBriefing(opts);
+  }
+}
