+/**
+ * Generate the per-activation briefing markdown for the reviewer executor.
+ *
+ * Sections (in order):
+ *   1. Preamble — automated context, no interactive session
+ *   2. ## Identity
+ *   3. ## Your claimed task
+ *   4. ## Reviewer context
+ *   5. ## What you must do
+ *   6. ## Model
+ *   7. ## Rules
+ */
+export function generateReviewerBriefing(mgmtDir: string, opts: ReviewerBriefingOpts): string {
+  const {
+    taskId,
+    featureId,
+    taskBranch,
+    taskRepo,
+    taskRepoRoot,
+    workspaceRoot,
+    prUrl,
+    gitAuthorEmail,
+    gitAuthorName,
+    reviewerModel,
+    resultPath,
+    reviewCycleCount,
+    maxReviewCycles,
+  } = opts;
+
+  const taskTitle = readTaskTitle(mgmtDir, featureId, taskId);
+
+  return joinSections(
+    preambleSection(),
+    identitySection({ gitAuthorEmail, gitAuthorName }),
+    taskContextSection("Your claimed task", {
+      taskId,
+      featureId,
+      taskTitle,
+      taskBranch,
+      taskRepo,
+      taskRepoRoot,
+      workspaceRoot,
+      prUrl,
+    }),
+    [
+      "## Reviewer context",
+      "",
+      `Review cycle:     ${reviewCycleCount + 1} of ${maxReviewCycles}`,
+      `Result path:      ${resultPath}`,
+      `Max cycles (env): MAX_REVIEW_CYCLES=${maxReviewCycles}`,
+      "",
+      "If review cycle count reaches the max, write `terminal_status: escalate` immediately.",
+    ],
+    [
+      "## What you must do",
+      "",
+      `Run \`/review-pr\` to evaluate the pull request at \`${prUrl}\`.`,
+      "",
+      "The skill handles the full reviewer contract:",
+      "  1. Check cycle limit — escalate immediately if at/over max.",
+      "  2. Read product-spec.md + technical-design.md + tasks.md for context.",
+      "  3. Fetch the PR diff.",
+      "  4. Wait for CI check-runs to resolve (pass or fail).",
+      "  5. Evaluate the diff against the rubric in",
+      "     `technical_skills/review-pr/references/review_criteria.md`.",
+      "  6. Apply the decision table (CI fail / any 🔴/🟡 → REQUEST_CHANGES; else APPROVE).",
+      "  7. Post a GitHub APPROVE or REQUEST_CHANGES review.",
+      "  8. If APPROVE: squash-merge the implementation PR via GitHub REST API (before writing result.json).",
+      `  9. Write \`result.json\` to \`${resultPath}\` with:`,
+      '     `{ "terminal_status": "passed" | "change_requested" | "escalate", ... }`',
+      "",
+      "Complete all steps without stopping or asking for confirmation.",
+    ],
+    modelSection(reviewerModel),
+    [
+      "## Rules",
+      "",
+      "- Do not ask clarifying questions.",
+      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
+      "- Read documents in the specified order before evaluating the diff.",
+      "- Every finding must cite the exact file path and line from the diff.",
+      "- Every finding must cite the specific rubric criterion that was violated.",
+      "- Do not request changes that contradict the approved product spec.",
+      `- Always write \`${resultPath}\` as the final step — even on failure.`,
+      "- If any shell command exits with code 127 (command not found), write",
+      `  \`{"terminal_status":"escalate","verdict":"escalate","confidence":0,"notes":"missing_tool"}\``,
+      `  to \`${resultPath}\` and stop immediately.`,
+    ],
+  );
+}
